use std::{fs,path::Path,collections::BTreeMap};use serde_json::{json,Value};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-g1-quarter-current";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);let src=r.join("candidate");let base=read("/tmp/zopro-grouping-module/production-source-manifest.json");let mut pins=BTreeMap::new();let mut changed=Vec::new();for(p,h)in base["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());let path=src.join(p);let actual=hash(&path);if actual!=h.as_str().unwrap(){changed.push(p.clone());}pins.insert(path.display().to_string(),actual);}assert_eq!(changed,vec!["crates/zopro-bn254/src/lib.rs","crates/zopro-core/src/msm.rs","crates/zopro-core/src/simd.rs"]);
 for rel in ["crates/zopro-bn254/src/point_domain.rs","crates/zopro-core/src/msm/g1_quarter.rs","crates/zopro-bench/examples/cpu-sdk.rs","crates/zopro-bench/examples/support/perf.rs"]{let p=src.join(rel);pins.insert(p.display().to_string(),hash(p));}for rel in ["setup.rs","design.md"]{let p=r.join(rel);pins.insert(p.display().to_string(),hash(p));}save(r.join("source-pins.json"),&json!(pins));save(r.join("implementation-audit.json"),&json!({"status":"pass","accepted_manifest_sha256":hash("/tmp/zopro-grouping-module/production-source-manifest.json"),"base_files":170,"unchanged_originals":167,"changed":changed,"new_modules":["bn254/point_domain","core/msm/g1_quarter"],"known_algebra_rebase":true,"new_scratch_Vecs":0,"point_copies_or_tables":0,"typed_workspace_source_unchanged":true,"production_sources_unchanged":true,"adopted":false}));
 let mut plan=read("/tmp/zopro-g2-tree-sdk/native-plan.json");let rendered=serde_json::to_string(&plan).unwrap().replace("/tmp/zopro-g2-tree-sdk",R).replace("zopro_g2_prefix_tree","zopro_g1_quarter_current").replace("target-cpu=znver4","target-cpu=native");plan=serde_json::from_str(&rendered).unwrap();plan["source_pins"]=json!(r.join("source-pins.json"));plan["environment"].as_object_mut().unwrap().remove("ZOPRO_CPU_G2_PREFIX_TREE");plan["environment"]["ZOPRO_CPU_G1_QUARTER_CURRENT"]=json!("1");let core=&mut plan["steps"][2];core["required_tests"]=json!(["msm::g1_quarter::tests::current_quarter_unsigned_tail_and_shared_scratch_reuse","msm::g1_quarter::tests::current_quarter_signed_tail_and_shared_scratch_reuse","msm::g1_quarter::tests::switching_kernels_reuses_the_same_record_allocation"]);let mut field=core.clone();field["name"]=json!("field");let argv=field["argv"].as_array_mut().unwrap();let at=argv.iter().position(|s|s=="zopro-core").unwrap();argv[at]=json!("zopro-bn254");field["required_tests"]=json!(["point_domain::tests::raw_point_domain_and_current_cios_products_match_scalar_oracles","point_domain::tests::uniform_signed_numerators_cover_every_sign_mask_and_negative_zero","point_domain::tests::widened_current_cios_matches_independent_ark_at_lazy_boundaries"]);plan["steps"].as_array_mut().unwrap().insert(2,field);for s in plan["steps"].as_array_mut().unwrap(){if s["name"]=="portable-consumers"{s["environment"]["RUSTFLAGS"]=json!(s["environment"]["RUSTFLAGS"].as_str().unwrap().replace("target-cpu=native","target-cpu=x86-64"));}}save(r.join("native-plan.json"),&plan);println!("Pinned{}inputs; known quarter algebra on current backend, shared scratch",pins.len());}
